// ARQUIVO: src/renderer/src/App.tsx
import { useState, useCallback } from 'react'
import type { Conversation } from './types'
import { Sidebar } from './components/Sidebar'
import { useUI } from './ui/UiProvider'
import { firstVisibleId } from '../../shared/archive'

/** 
 * Componente principal da aplicação. Gerencia o estado das conversas, a conversa ativa e
 * delega ações de UI para os componentes filhos. A persistência é tratada pelo projectStore
 * via chamadas explícitas ou gatilhos do Electron IPC.
 */
export function App(): JSX.Element {
  const ui = useUI()

  // Estado local das conversas. Em produção, este estado é sincronizado com o projectStore.
  const [conversations, setConversations] = useState<Conversation[]>([])
  const [activeId, setActiveId] = useState<string | null>(null)
  const [busyIds, setBusyIds] = useState<Set<string>>(new Set())

  // Agrupa conversas por projeto para a sidebar.
  const projects = conversations.reduce((acc: { path: string; name: string; conversations: Conversation[] }[], c) => {
    let proj = acc.find(p => p.path === c.cwd)
    if (!proj) {
      proj = { path: c.cwd, name: c.cwd.split(/[\\/]/).pop() || c.cwd, conversations: [] }
      acc.push(proj)
    }
    proj.conversations.push(c)
    return acc
  }, [])

  // Conversas recentes (não arquivadas), ordenadas por updatedAt.
  const recents = conversations
    .filter(c => !c.archived)
    .sort((a, b) => b.updatedAt - a.updatedAt)
    .slice(0, 10)

  /** 
   * Handler para arquivar/desarquivar conversas.
   * Atualiza o estado local e dispara a persistência no projectStore.
   */
  const handleArchive = useCallback((id: string, archived: boolean): void => {
    setConversations(prev => prev.map(c => c.id === id ? { ...c, archived } : c))

    // Se arquivou a conversa ativa, seleciona a próxima visível conforme especificação.
    if (archived && activeId === id) {
      const next = firstVisibleId(conversations.filter(c => c.id !== id))
      setActiveId(next)
    }

    // Persiste a mudança no disco.
    ui.saveProject?.()
  }, [activeId, conversations, ui])

  return (
    <div className="app">
      <Sidebar
        collapsed={false}
        onToggleCollapse={() => {}}
        projects={projects}
        recents={recents}
        activeId={activeId}
        busyIds={busyIds}
        onSelect={(id) => setActiveId(id)}
        onNewChat={() => {}}
        onNewProject={() => {}}
        onNewChatIn={() => {}}
        onRename={() => {}}
        onDelete={() => {}}
        onSelectResult={() => {}}
        onArchive={handleArchive}
      />
    </div>
  )
}
